// The producer owns `out`: sole sender, and the only closer.
func gen(nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out) // owner closes when done
		for _, n := range nums {
			out <- n
		}
	}()
	return out // receive-only: callers cannot send or close
}

func main() {
	for v := range gen(1, 2, 3) {
		fmt.Println(v)
	}
	// Output:
	// 1
	// 2
	// 3
}

// Two-stage pipeline: gen -> square, connected only by channels.
func square(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in { // ends when `in` is closed
			out <- n * n
		}
	}()
	return out
}

func main() {
	for s := range square(gen(2, 3, 4)) {
		fmt.Println(s)
	}
	// Output:
	// 4
	// 9
	// 16
}

// Fan-in: merge several producer channels onto one output.
func merge(cs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	for _, c := range cs {
		wg.Add(1)
		go func(c <-chan int) {
			defer wg.Done()
			for v := range c {
				out <- v
			}
		}(c)
	}
	go func() { wg.Wait(); close(out) }() // close once all senders finish
	return out
}

