// Fixed pool of 3 workers draining a jobs channel.
func pool(jobs <-chan int, results chan<- int) {
	var wg sync.WaitGroup
	for w := 0; w < 3; w++ { // exactly 3 concurrent workers
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs { // ends when jobs is closed
				results <- j * j
			}
		}()
	}
	wg.Wait()
	close(results)
}

