// A bounded queue = bounded memory. Producer blocks when full.
func main() {
	jobs := make(chan int, 2) // slack of 2; then backpressure kicks in
	go func() {
		for i := 1; i <= 4; i++ {
			jobs <- i // blocks once 2 are queued and none consumed
			fmt.Println("queued", i)
		}
		close(jobs)
	}()
	time.Sleep(10 * time.Millisecond) // slow consumer
	for v := range jobs {
		fmt.Println("consumed", v)
	}
}

// errgroup: bounded fan-out that cancels all on the first error.
func fetchAll(ctx context.Context, ids []int, get func(context.Context, int) error) error {
	g, ctx := errgroup.WithContext(ctx) // ctx cancelled on first error
	g.SetLimit(5)                       // at most 5 concurrent
	for _, id := range ids {
		id := id
		g.Go(func() error {
			return get(ctx, id) // returning an error cancels the group
		})
	}
	return g.Wait() // returns the first non-nil error, if any
}

