package main

import (
	"context"
	"fmt"
)

// gen owns `out`: it is the only sender and closes it.
func gen(ctx context.Context, nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out) // owner closes when done
		for _, n := range nums {
			select {
			case out <- n:
			case <-ctx.Done(): // stop early on cancellation
				return
			}
		}
	}()
	return out
}

// square is a stage: read in, transform, send out.
func square(ctx context.Context, in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			select {
			case out <- n * n:
			case <-ctx.Done():
				return
			}
		}
	}()
	return out
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	for s := range square(ctx, gen(ctx, 1, 2, 3, 4)) {
		fmt.Println(s)
	}
}

