package main

import (
	"context"

	"golang.org/x/sync/errgroup"
)

// Bounded to 5 concurrent fetches; cancels all on first error.
func fetchAll(ctx context.Context, urls []string, get func(context.Context, string) error) error {
	g, ctx := errgroup.WithContext(ctx) // ctx is cancelled on first error
	sem := make(chan struct{}, 5)       // semaphore: at most 5 in flight
	for _, u := range urls {
		u := u // capture per iteration (safe even pre-1.22)
		g.Go(func() error {
			select {
			case sem <- struct{}{}: // acquire a slot
			case <-ctx.Done():
				return ctx.Err()
			}
			defer func() { <-sem }() // release the slot
			return get(ctx, u)       // first error cancels the group
		})
	}
	return g.Wait() // returns the first non-nil error, if any
}

