package solution

import (
	"context"

	"golang.org/x/sync/errgroup"
)

func ParallelMap(ctx context.Context, in []int, limit int, fn func(context.Context, int) (int, error)) ([]int, error) {
	if limit < 1 {
		limit = 1
	}
	out := make([]int, len(in)) // pre-sized; each index written exactly once
	g, ctx := errgroup.WithContext(ctx)
	g.SetLimit(limit) // at most `limit` goroutines run concurrently
	for i, v := range in {
		i, v := i, v // capture per iteration
		g.Go(func() error {
			r, err := fn(ctx, v)
			if err != nil {
				return err // cancels ctx; other tasks observe it
			}
			out[i] = r // distinct index -> no data race, order preserved
			return nil
		})
	}
	if err := g.Wait(); err != nil {
		return nil, err
	}
	return out, nil
}

