package solution

import (
	"context"
	"errors"
	"reflect"
	"testing"
)

func TestParallelMap_Order(t *testing.T) {
	in := []int{1, 2, 3, 4, 5}
	got, err := ParallelMap(context.Background(), in, 2, func(_ context.Context, x int) (int, error) {
		return x * x, nil
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := []int{1, 4, 9, 16, 25}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %v want %v", got, want)
	}
}

func TestParallelMap_FirstError(t *testing.T) {
	boom := errors.New("boom")
	_, err := ParallelMap(context.Background(), []int{1, 2, 3}, 3, func(_ context.Context, x int) (int, error) {
		if x == 2 {
			return 0, boom
		}
		return x, nil
	})
	if !errors.Is(err, boom) {
		t.Errorf("want boom, got %v", err)
	}
}

