// Consumer cancels (defer cancel()) when it stops early, freeing senders.

func SumSquares(ctx context.Context, nums []int, workers int) int {
	if workers < 1 {
		workers = 1
	}
	jobs := make(chan int, len(nums))
	for _, n := range nums {
		jobs <- n
	}
	close(jobs) // lets `for range jobs` terminate

	partials := make(chan int, workers)
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			sum := 0
			for n := range jobs {
				select {
				case <-ctx.Done():
					return // honor cancellation; no leak
				default:
					sum += n * n
				}
			}
			partials <- sum
		}()
	}
	go func() { wg.Wait(); close(partials) }()

	total := 0
	for p := range partials { // commutative add; order irrelevant
		total += p
	}
	return total
}

package solution

import (
	"context"
	"sync"
)

// Merge fans several input channels into one output. It closes the output
// when all inputs are drained, and every forwarding goroutine exits cleanly
// if the consumer cancels ctx (no leak).
func Merge(ctx context.Context, cs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(cs))
	for _, c := range cs {
		go func(c <-chan int) {
			defer wg.Done()
			for v := range c { // ends when this input is closed
				select {
				case out <- v:
				case <-ctx.Done(): // consumer gave up -> exit, no leak
					return
				}
			}
		}(c)
	}
	// The sole closer: run only after every forwarder has finished.
	go func() {
		wg.Wait()
		close(out)
	}()
	return out // receive-only: consumers can't send or close
}
